<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { api, type Data } from '../api/client'
import { useRequest } from '../composables/useRequest'
import { useAuthStore } from '../stores/auth'
import { dateText } from '../lib/ui'
import Icon from '../components/Icon.vue'
import EmptyState from '../components/EmptyState.vue'
import BarChart from '../components/BarChart.vue'
const auth = useAuthStore(); const { run, busy, error } = useRequest()
const summary = ref<Data | null>(null); const today = ref<Data>({ tasks: [], courses: [], exams: [] }); const analytics = ref<Data>({ trend: [], subjects: [] })
const hour = new Date().getHours(); const greeting = hour < 6 ? '夜深了' : hour < 12 ? '上午好' : hour < 18 ? '下午好' : '晚上好'
const date = new Date().toLocaleDateString('zh-CN', { month: 'long', day: 'numeric', weekday: 'long' })
const stats = computed(() => summary.value ? [{ title: '今日学习', value: summary.value.study_minutes, unit: '分钟', icon: 'clock', note: '每一份专注都值得记录' }, { title: '任务完成率', value: summary.value.task_rate, unit: '%', icon: 'check', note: `累计 ${summary.value.task_done} / ${summary.value.task_total} 项完成` }, { title: '知识资料', value: summary.value.documents, unit: '份', icon: 'layers', note: '构建自己的多专业知识体系' }, { title: '练习题目', value: summary.value.questions || 0, unit: '题', icon: 'question', note: '用练习检验理解' }] : [])
async function load() { await run(async () => { const [s, t, a] = await Promise.all([api.get('/dashboard/summary'), api.get('/dashboard/today'), api.get('/analytics/overview')]); summary.value = s; today.value = t; analytics.value = a }) }
async function complete(task: Data) { await run(async () => { await api.post(`/tasks/${task.id}/complete`); const [s, t] = await Promise.all([api.get('/dashboard/summary'), api.get('/dashboard/today')]); summary.value = s; today.value = t }, '已完成一项学习任务') }
function daysUntil(value: string) { return Math.max(0, Math.ceil((new Date(value).getTime() - Date.now()) / 86400000)) }
onMounted(load)
</script>
<template><section class="page dashboard-page"><div class="welcome"><div><h1>{{ greeting }}，{{ auth.user?.display_name || '学习者' }} <Icon class="greeting-spark" name="spark" :size="24" /></h1><p>把今天的专注，变成明天的底气。</p><p class="page-context">{{ date }} · 新的一天，新的收获</p></div><RouterLink class="primary" to="/knowledge"><Icon name="layers" :size="17" /> 浏览多专业知识库 <Icon name="arrow" :size="17" /></RouterLink></div><div v-if="error" class="error-banner" role="alert">{{ error }}<button class="text-button" @click="load">重新加载</button></div><div v-if="busy && !summary" class="loading-panel">正在整理你的学习空间…</div><div class="stat-grid"><article v-for="(item, index) in stats" :key="item.title" class="stat-card" :class="{ accent: index === 0 }"><div class="stat-top"><span>{{ item.title }}</span><div class="stat-icon"><Icon :name="item.icon" /></div></div><div class="stat-value">{{ item.value }}<small>{{ item.unit }}</small></div><div class="stat-note">{{ item.note }}</div></article></div><div class="dashboard-columns"><section class="panel"><div class="panel-head"><div><h2>学习的节奏</h2><p>近 14 天 · 每一天的真实积累</p></div><RouterLink to="/analytics" class="text-button">查看数据 <Icon name="arrow" :size="15" /></RouterLink></div><BarChart :items="analytics.trend" /></section><section class="panel"><div class="panel-head"><div><h2>今日待办 <span class="count-badge">{{ today.tasks.length }}</span></h2><p>从一个小目标开始</p></div><RouterLink class="icon-button soft" to="/learning" title="管理任务"><Icon name="plus" /></RouterLink></div><div v-for="task in today.tasks.slice(0, 4)" :key="task.id" class="mini-task"><button class="task-check" :disabled="busy" :aria-label="`完成 ${task.title}`" @click="complete(task)"></button><RouterLink :to="{ path: '/learning', query: { id: task.id } }" class="grow"><strong>{{ task.title }}</strong><small>{{ task.estimated_minutes }} 分钟 · {{ task.due_date ? dateText(task.due_date) : '无截止日期' }}</small></RouterLink><span :class="`priority p${task.priority}`">{{ ['', '高', '中', '低'][task.priority] }}</span></div><EmptyState v-if="!today.tasks.length" title="今天的清单很轻盈" description="给今天设定一个可以完成的小目标。" icon="check"><RouterLink to="/learning" class="text-button">创建学习任务 →</RouterLink></EmptyState><RouterLink v-if="today.tasks.length" to="/learning" class="panel-bottom-link">查看全部任务 →</RouterLink></section></div><div class="dashboard-columns"><section class="panel"><div class="panel-head"><div><h2>近期考试</h2><p>留足准备时间，少一些匆忙</p></div><RouterLink to="/learning?tab=exams" class="text-button">管理 <Icon name="arrow" :size="15" /></RouterLink></div><div v-for="exam in today.exams.slice(0, 2)" :key="exam.id" class="exam-row"><div class="date-block"><strong>{{ exam.exam_date.slice(8, 10) }}</strong><span>{{ exam.exam_date.slice(5, 7) }} 月</span></div><div class="grow"><strong>{{ exam.subject }}</strong><small>{{ exam.location || '地点待定' }} · {{ dateText(exam.exam_date) }}</small></div><div class="countdown">{{ daysUntil(exam.exam_date) }}<small>天后</small></div></div><EmptyState v-if="!today.exams.length" title="暂时没有考试安排" icon="calendar"><RouterLink to="/learning?tab=exams" class="text-button">添加考试 →</RouterLink></EmptyState></section><section class="focus-card"><div class="focus-icon"><Icon name="spark" :size="28" /></div><h2>计划不用完美，<br>先迈出具体的一步。</h2><p>从每天可以坚持的时间开始。<br>制定、调整、执行，让目标落到日历上。</p><RouterLink class="text-button" to="/plans">制定我的学习计划 <Icon name="arrow" :size="17" /></RouterLink></section></div><section v-if="today.courses.length" class="panel"><div class="panel-head"><h2>今天的课程</h2><RouterLink to="/learning?tab=courses" class="text-button">查看课程表 →</RouterLink></div><div class="course-strip"><div v-for="course in today.courses" :key="course.id" class="course-mini"><span class="pill">{{ course.start_time }} — {{ course.end_time }}</span><h3>{{ course.name }}</h3><p>{{ course.classroom || '地点待定' }} · {{ course.teacher || '教师未填写' }}</p></div></div></section><section class="quick-grid"><RouterLink v-for="item in [{ to: '/documents', icon: 'file', title: '读懂一份资料', desc: '提炼重点，形成自己的知识' }, { to: '/questions', icon: 'question', title: '检验一次理解', desc: '针对性练习，及时获得反馈' }, { to: '/plans', icon: 'calendar', title: '把目标变成行动', desc: '制定计划，拆解为每日任务' }]" :key="item.to" :to="item.to" class="quick-card"><div class="quick-icon"><Icon :name="item.icon" /></div><div><strong>{{ item.title }}</strong><p>{{ item.desc }}</p></div><Icon name="arrow" :size="17" /></RouterLink></section></section></template>
